target='.....((((((((...)))).((((((((...))))..((((...))))..((((...)))))))).((((...))))))))....................'
# Build sequence: GGGGGGGGGGGGGG for strong GC, but need unpaired regions weak (A) to avoid alt folds
seq=list('A'*102)
# helices: use GC for outermost, CG etc. Set paired positions to G/C
pairs={}
stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
# assign: 5' of pair = G, 3' of pair = C, but alternate GC to be safe; unpaired = A
for i in range(102):
    if i in pairs:
        seq[i]='G' if i<pairs[i] else 'C'
    else:
        seq[i]='A'
print(''.join(seq))
print(len(seq))
"

